theorem gaokaoformal_g_380 
(n : ℕ) 
(hn : 2 ≤ n) : 
let S : Set (Fin n → Fin 2) := {X | ∀ (i : Fin n), X i ∈ ({0, 1} : Set (Fin 2))};
let diff (A B : Fin n → Fin 2) : Fin n → Fin 2 := fun i => |(A i).val - (B i).val|;
let d (A B : Fin n → Fin 2) : ℝ := ∑ i : Fin n, |(A i).val - (B i).val|;
∀ (A B C : Fin n → Fin 2), (A ∈ S ∧ B ∈ S ∧ C ∈ S) → (diff A B ∈ S) ∧ (d (diff A C) (diff B C) = d A B) := by sorry

theorem gaokaoformal_g_448 :
∃ (fixed: ℝ×ℝ),
    ∀ (b: ℝ) (f: ℝ→ ℝ)(p q: ℝ),
        (∀ (x:ℝ), f x = x^2 + 2*x + b) ∧ 
        (f p = 0 ∧ f q = 0 ∧ p ≠ q ∧ p ≠ 0 ∧ q ≠ 0) →
        ∃ (center:ℝ×ℝ), 
        let CP := Real.sqrt ((center.1 - p)^2 + (center.2)^2);
        let CQ := Real.sqrt ((center.1 - q)^2 + (center.2)^2);
        let CY := Real.sqrt ((center.1)^2 + (center.2 - f 0)^2);
        let CF := Real.sqrt ((center.1 - fixed.1)^2 + (center.2 - fixed.2)^2);
        CP = CQ ∧ CQ = CY ∧ CY = CF := by sorry

theorem gaokaoformal_g_108 
(C: Set (ℝ × ℝ))
(hC: C = {(x,y) | y^2 = 2*x})
(A B: ℝ×ℝ)
(hAB: A = (2,0) ∧ B = (-2,0))
(l: Set (ℝ×ℝ))
(a b:ℝ)
(hab: a≠0 ∨ b≠0)
(hl: l = {(x,y) | a*(x-A.1) + b*(y-A.2) = 0}) :
∃ M N : ℝ × ℝ, M ∈ l ∩ C ∧ N ∈ l ∩ C ∧ M ≠ N →
let innerABMB := (A.1 - B.1)*(M.1 - B.1) + (A.2 - B.2)*(M.2 - B.2);
let innerABNB := (A.1 - B.1)*(N.1 - B.1) + (A.2 - B.2)*(N.2 - B.2);
let normAB := Real.sqrt ((A.1 - B.1)^2 + (A.2 - B.2)^2);
let normMB := Real.sqrt ((M.1 - B.1)^2 + (M.2 - B.2)^2);
let normNB := Real.sqrt ((N.1 - B.1)^2 + (N.2 - B.2)^2);
Real.arccos (innerABMB / (normAB*normMB)) = Real.arccos (innerABNB / (normAB*normNB)) := by sorry
